import type { Authenticator, AuthResult } from "../contracts";
import { ApiKeyAuthenticator } from "../providers/ApiKeyAuthenticator";
export class SessionService {
  private sessions = new Map<string, AuthResult>();
  static createDefault() { return new SessionService(new ApiKeyAuthenticator()); }
  constructor(private authenticator: Authenticator) {}
  async login(id: string, input: string) {
    const result = await this.authenticator.authenticate(input);
    this.sessions.set(id, result);
    return result.accessToken;
  }
  async renew(id: string, now: number) {
    const session = this.sessions.get(id);
    if (!session) throw new Error("missing session");
    if (session.expiresAt > now) return session.accessToken;
    if (!session.refreshToken) throw new Error("refresh token required");
    const next = await this.authenticator.refresh(session.refreshToken);
    this.sessions.set(id, next);
    return next.accessToken;
  }
  logout(id: string) { this.sessions.delete(id); }
}

files.src/auth/providers/ApiKeyAuthenticator.t:
import type { Authenticator, AuthResult } from "../contracts";
import { SessionService } from "../session/SessionService";
export class ApiKeyAuthenticator implements Authenticator {
  async authenticate(key: string): Promise<AuthResult> {
    return { accessToken: key, expiresAt: Number.MAX_SAFE_INTEGER };
  }
  async refresh(_refreshToken: string): Promise<AuthResult> {
    throw new Error("API keys do not refresh");
  }
  revokeLocalSession(sessions: SessionService, id: string) { sessions.logout(id); }
}

